declare module "*.css";
declare module "*.module.css";

// SCSS / SASS
declare module "*.scss";
declare module "*.sass";
declare module "*.module.scss";
declare module "*.module.sass";

// LESS
declare module "*.less";
declare module "*.module.less";

// Stylus
declare module "*.styl";
declare module "*.module.styl";

// Imágenes
declare module "*.png";
declare module "*.jpg";
declare module "*.jpeg";
declare module "*.gif";
declare module "*.svg";
declare module "*.webp";
declare module "*.avif";

// Fuentes
declare module "*.woff";
declare module "*.woff2";
declare module "*.ttf";
declare module "*.otf";
declare module "*.eot";

// Archivos multimedia
declare module "*.mp4";
declare module "*.webm";
declare module "*.ogg";
declare module "*.mp3";
declare module "*.wav";

// JSON (normalmente TS ya lo soporta, pero por si acaso)
declare module "*.json";

// Otros archivos
declare module "*.txt";
declare module "*.md";